mapper.select:
SELECT ge.FID AS eas_id, ge.FBILLID AS voucher_eas_id, ge.FDESCRIPTION AS voucher_summary, toc.FNUMBER AS org_id, tbm.fnumber AS contract_code, tbm.FNAME_L2 AS contract_name, tbc1.FNUMBER AS client_code, tbc1.FNAME_L2 AS client_name, gac.FNUMBER AS account_code, gac.FNAME_L2 AS account_name, tba1.FBANKACCOUNTNUMBER AS bank_number, tbg1.FNUMBER AS bill_contract_code, tbp.FNUMBER AS period_code, DECODE(GE.FENTRYDC, '1', 'DR', 'CR') AS debit_credit_type, NULLIF(DECODE(GE.FENTRYDC, '1', COALESCE(GAV.FORIGINALAMOUNT,GE.FORIGINALAMOUNT), '0'), 0) AS debit_amount, NULLIF(DECODE(GE.FENTRYDC, '0', COALESCE(GAV.FORIGINALAMOUNT,GE.FORIGINALAMOUNT), '0'), 0) AS credit_amount FROM HXORACLE.T_GL_VOUCHER t INNER JOIN HXORACLE.T_ORG_COMPANY toc ON toc.FID =t.FCOMPANYID INNER JOIN HXORACLE.T_BD_PERIOD TBP ON TBP.FID =t.FPERIODID INNER JOIN HXORACLE.T_GL_VOUCHERENTRY GE ON t.FID = GE.FBILLID INNER JOIN HXORACLE.T_BD_CURRENCY tbc ON GE.FCURRENCYID =tbc.FID LEFT JOIN HXORACLE.T_GL_VOUCHERASSISTRECORD GAV ON GE.FID =GAV.FENTRYID LEFT JOIN HXORACLE.T_BD_ASSISTANTHG HG ON HG.FID =GAV.FASSGRPID INNER JOIN HXORACLE.T_BD_ACCOUNTVIEW GAC ON GE.FACCOUNTID =GAC.FID LEFT OUTER JOIN HXORACLE.T_BD_MATERIAL tbm ON HG.FMATERIALID =TBM.FID LEFT OUTER JOIN HXORACLE.T_BD_CUSTOMER tbc1 ON HG.FCUSTOMERID =TBC1.FID LEFT OUTER JOIN HXORACLE.T_BD_ACCOUNTBANKS TBA1 ON TBA1.FID =HG.FBANKACCOUNTID LEFT OUTER JOIN HXORACLE.T_BD_GENERALASSTACTTYPE tbg1 ON tbg1.FID =HG.FGENERALASSACTTYPE3ID WHERE tbp.FNUMBER = #{periodCode} and to_char(t.FBOOKEDDATE,'yyyy-mm-dd') = #{voucherDate} AND t.FABSTRACT NOT IN ('结转损益','结转损益-资产减值损失','结转损益6041.03','结转损益6701.04')
AND t.FBIZSTATUS = #{bizStatus}
and tbm.fnumber in
#{item}

SELECT ${periodCode} as period_code, toc.FNUMBER AS org_id, tbm.fnumber AS contract_code, tbc1.FNUMBER AS client_code, tbg1.FNUMBER AS bill_contract_code, ga.FNUMBER AS account_code, ga.FNAME_L2 AS account_name, sum(gba.FENDBALANCEFOR) AS account_balance FROM HXORACLE.T_GL_AssistBalance_5F GBA LEFT OUTER JOIN HXORACLE.T_ORG_COMPANY toc ON toc.FID = gba.FORGUNITID LEFT OUTER JOIN HXORACLE.T_BD_ACCOUNTVIEW GA ON GBA.FACCOUNTID = GA.FID LEFT OUTER JOIN HXORACLE.T_BD_CURRENCY tbc ON gba.FCURRENCYID = tbc.FID LEFT OUTER JOIN HXORACLE.T_BD_ASSISTANTHG GS ON GBA.FASSISTGRPID = GS.FID LEFT OUTER JOIN HXORACLE.T_BD_MATERIAL tbm ON GS.FMATERIALID = TBM.FID LEFT OUTER JOIN HXORACLE.T_BD_CUSTOMER tbc1 ON GS.FCUSTOMERID = TBC1.FID LEFT OUTER JOIN T_BD_GENERALASSTACTTYPE tbg1 ON tbg1.FID = GS.FGENERALASSACTTYPE3ID WHERE GBA.FPERIOD = #{periodCode}
and tbm.fnumber in
#{item}
GROUP BY toc.FNUMBER, tbm.fnumber, tbc1.FNUMBER, tbg1.FNUMBER, ga.FNUMBER, ga.FNAME_L2

SELECT TO_NUMBER(${periodCode}) as period_code, toc.FNUMBER AS org_id, CAST(tbm.fnumber AS VARCHAR2(80)) AS contract_code, CAST(tbc1.FNUMBER AS VARCHAR2(80)) AS client_code, CAST(tbg1.FNUMBER AS VARCHAR2(80)) AS bill_contract_code, tbc.FISOCODE AS currency_code, ga.FNUMBER AS account_code, ga.FNAME_L2 AS account_name, sum(gba.FBEGINBALANCEFOR) AS begin_balance, sum(gba.FENDBALANCEFOR) AS end_balance, sum(gba.FDEBITFOR) AS debit_amount, sum(gba.FCREDITFOR) AS credit_amount, sum(gba.FYEARDEBITFOR) AS year_debit_amount, sum(gba.FYEARCREDITFOR) AS year_credit_amount FROM HXORACLE.T_GL_AssistBalance_5F GBA LEFT OUTER JOIN HXORACLE.T_ORG_COMPANY toc ON toc.FID = gba.FORGUNITID LEFT OUTER JOIN HXORACLE.T_BD_ACCOUNTVIEW GA ON GBA.FACCOUNTID = GA.FID LEFT OUTER JOIN HXORACLE.T_BD_CURRENCY tbc ON gba.FCURRENCYID = tbc.FID LEFT OUTER JOIN HXORACLE.T_BD_ASSISTANTHG GS ON GBA.FASSISTGRPID = GS.FID LEFT OUTER JOIN HXORACLE.T_BD_MATERIAL tbm ON GS.FMATERIALID = TBM.FID LEFT OUTER JOIN HXORACLE.T_BD_CUSTOMER tbc1 ON GS.FCUSTOMERID = TBC1.FID LEFT OUTER JOIN T_BD_GENERALASSTACTTYPE tbg1 ON tbg1.FID = GS.FGENERALASSACTTYPE3ID WHERE GBA.FPERIOD = #{periodCode}
AND toc.FNUMBER = #{orgId}
GROUP BY toc.FNUMBER, tbm.fnumber, tbc1.FNUMBER, tbg1.FNUMBER,tbc.FISOCODE, ga.FNUMBER, ga.FNAME_L2 union SELECT gb.FPERIOD as period_code, toc.FNUMBER AS org_id, '' AS contract_code, '' AS client_code, '' AS bill_contract_code, tbc.FISOCODE AS currency_code, ga.FNUMBER AS account_code, ga.FNAME_L2 AS account_name, sum(gb.FBEGINBALANCEFOR) AS begin_balance, sum(gb.FENDBALANCEFOR) AS end_balance, sum(gb.FDEBITFOR) AS debit_amount, sum(gb.FCREDITFOR) AS credit_amount, sum(gb.FYEARDEBITFOR) AS year_debit_amount, sum(gb.FYEARCREDITFOR) AS year_credit_amount FROM HXORACLE.T_GL_ACCOUNTBALANCE_5F gb LEFT OUTER JOIN HXORACLE.T_ORG_COMPANY toc ON toc.FID = gb.FORGUNITID LEFT OUTER JOIN HXORACLE.T_BD_ACCOUNTVIEW GA ON GB.FACCOUNTID = GA.FID LEFT OUTER JOIN HXORACLE.T_BD_CURRENCY tbc ON gb.FCURRENCYID = tbc.FID WHERE GB.FPERIOD = #{periodCode} AND toc.FNUMBER IN ('01-C0001','02-C0001','30001','80001') AND ga.FNUMBER IN ('1231.05', '1510.01', '1531.02', '2241.18', '6051.99', '6701.22', '1231.02.01', '1231.02.04', '1231.02.99', '1510.02', '1510.04.01', '1510.04.03', '2202.04.01', '2202.04.02', '2202.04.06' ) GROUP BY gb.FPERIOD,toc.FNUMBER, tbc.FISOCODE, ga.FNUMBER, ga.FNAME_L2
